import { booleanAttribute, Directive, HostListener, inject, input, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { BaseComponent } from 'primeng/basecomponent';
import { TreeTableStyle } from './style/treetablestyle';
import type { TreeTable } from './treetable';
import { TREETABLE_INSTANCE } from './treetable-service';

@Directive({
    selector: '[ttSelectableRow]',
    standalone: true,
    host: {
        '[class]': 'cx("row")',
        '[attr.aria-selected]': 'selected()',
        '[attr.tabindex]': 'hostTabindex'
    },
    providers: [TreeTableStyle]
})
export class TTSelectableRow extends BaseComponent {
    rowNode = input<any>(undefined, { alias: 'ttSelectableRow' });

    ttSelectableRowDisabled = input(undefined, { transform: booleanAttribute });

    selected = signal<boolean | undefined>(undefined);

    _componentStyle = inject(TreeTableStyle);

    tt = inject<TreeTable>(TREETABLE_INSTANCE);

    constructor() {
        super();
        this.tt.tableService.selectionSource$.pipe(takeUntilDestroyed()).subscribe(() => {
            this.selected.set(this.tt.isSelected(this.rowNode()?.node));
        });
    }

    onInit() {
        if (this.isEnabled()) {
            this.selected.set(this.tt.isSelected(this.rowNode()?.node));
        }
    }

    @HostListener('click', ['$event'])
    onClick(event: Event) {
        if (this.isEnabled()) {
            this.tt.handleRowClick({
                originalEvent: event,
                rowNode: this.rowNode()
            });
        }
    }

    /**
     * Selectable rows are tab stops: Tab reaches the row (Enter/Space selects),
     * then continues to the focusables inside it — toggler, checkbox, editors.
     */
    get hostTabindex() {
        return this.isEnabled() ? 0 : null;
    }

    @HostListener('keydown', ['$event'])
    onKeyDown(event: KeyboardEvent) {
        if (event.target !== this.el?.nativeElement) {
            return;
        }

        switch (event.code) {
            case 'Enter':
            case 'Space':
                this.onEnterKey(event);
                break;

            case 'Tab':
                if (event.shiftKey) {
                    this.onShiftTabKey(event);
                }

                break;

            default:
                break;
        }
    }

    /**
     * Backwards navigation treats rows as the stops: Shift+Tab from a row lands
     * on the previous row, not on the last focusable inside it (the browser's
     * reverse order would visit checkbox/toggler first). Forward Tab stays
     * native — row, then into the row's focusables, then the next row. On the
     * first row nothing is intercepted, so focus exits the table backwards.
     */
    private onShiftTabKey(event: KeyboardEvent) {
        let sibling = this.el?.nativeElement.previousElementSibling as HTMLElement | null;

        while (sibling && sibling.getAttribute('tabindex') === null) {
            sibling = sibling.previousElementSibling as HTMLElement | null;
        }

        if (sibling) {
            sibling.focus();
            event.preventDefault();
        }
    }

    @HostListener('touchend', ['$event'])
    onTouchEnd(event: Event) {
        if (this.isEnabled()) {
            this.tt.handleRowTouchEnd(event);
        }
    }

    onEnterKey(event) {
        if (this.tt.selectionMode() === 'checkbox') {
            this.tt.toggleNodeWithCheckbox({
                originalEvent: event,
                rowNode: this.rowNode()
            });
        } else {
            this.onClick(event);
        }

        event.preventDefault();
    }

    isEnabled() {
        return this.ttSelectableRowDisabled() !== true;
    }
}
